UNITS = [
    {"id": "PEDS-U153", "ch": 19, "n": 1, "title": "Childhood Exanthems — Classification (1st–6th Disease)", "sec": "Classification · p80", "qs": [], "guide": "Childhood exanthems: Infectious diseases characterized by rash. Classification Arranged in order of historical importance. 1st disease Measles; 2nd disease Scarlet Fever; 3rd disease Rubella; 5th disease Erythema Infectiosum; 6th disease Roseola infantum/exanthema subitum."},
    {"id": "PEDS-U154", "ch": 19, "n": 2, "title": "Measles — Microbiology, Stages, Complications, Management", "sec": "Measles · p80", "qs": [], "guide": "Measles (ss RNA virus, _oviridae). Incubation 8-12 days; Respiratory droplets; Secondary attack rate >90%; Infectivity/isolation 4 days before to 5 days after onset of rash. 1. Prodromal Day 1-3 Fever (intensity ↑ after rash), 3C's Cough, Coryza, Conjunctivitis. 2. Enanthem Day 2-3 Koplik spot (white spot surrounded by reddish hue, usually opposite 2nd lower molar; Rice grain/grain of sand). 3. Exanthematous Day 4-8 Maculopapular, behind ear/face → downward trunk & extremities, leaves brownish pigmentation, ↑ fever after rash. Complications Acute m/c Otitis media, most severe Pneumonia (viral giant cell/HECHT; bacterial Staph aureus/Strep pneumoniae); Chronic SSPE (1 in 1,000,000, latent 7-13 yrs, myoclonic seizures, cognitive impairment, personality changes, Dx IgG anti-measles Ab in CSF, fatal). Management Supportive (nutrition, antipyretic, IV fluids); Vitamin A ↓ morbidity/mortality by 50%, 2 doses 24 hrs apart: >1 yr 1 lakh IU, <1 yr 1/2 lakh IU."},
    {"id": "PEDS-U155", "ch": 19, "n": 3, "title": "Scarlet Fever — Etiology, Features, Complications, Management", "sec": "Scarlet Fever · p81", "qs": [], "guide": "Etiology Group A β hemolytic streptococci → Toxin: Pyrogenic exotoxin (Erythrogenic toxin); Age 5-15 yrs. Clinical Fever, Sore throat, Tender anterior cervical lymphadenopathy, Strawberry tongue (D/t hypertrophy of papillae), Rash starts on 2nd day of fever (spares palms and soles), Fine maculopapular sandpaper rash (face, trunk, extremities), Pastia's lines (rash accentuation at skin creases). Post streptococcal complications Acute rheumatic fever, PSGN, Post streptococcal reactive arthritis. Management Investigations Throat swab culture; Treatment Oral Penicillin V for 10 days > Amoxicillin for 10 days."},
    {"id": "PEDS-U156", "ch": 19, "n": 4, "title": "Rubella — Microbiology, Clinical Features, Complications", "sec": "Rubella · p82", "qs": [], "guide": "Rubella AKA German measles/3 day measles (Similarity in C/P's). Etiology Togaviridae (ss RNA virus). Incubation 14-21 days; Respiratory droplets; Infectivity 5 days before - 6 days after onset of rash. Clinical 1. Rash First sign/starts Day 1 (without prodromal stage), Maculopapular, behind ear/face → downwards, No desquamation/discoloration after disappearance. 2. Enanthem Forchheimer spots (tiny rose lesions in oropharynx); Lymphadenopathy suboccipital, posterior auricular, anterior cervical. Complications 1. Post infectious thrombocytopenia (2-3 wks after infection, self-limiting) 2. Arthritis (older children) 3. Progressive Rubella Panencephalitis (PRP) most severe, features similar to SSPE."},
    {"id": "PEDS-U157", "ch": 19, "n": 5, "title": "Erythema Infectiosum (5th Disease) — Parvovirus B19", "sec": "Erythema Infectiosum · p83", "qs": [], "guide": "Etiology Parvovirus B19 (ss DNA virus). Incubation 4-28 days; Age >5 years. Clinical 1. Prodromal Fever 1-2 days. Exanthematous Stage 1 Slapped-cheek appearance, Facial flushing; Stage 2 Diffuse macular erythema (trunk & extremities); Stage 3 Central clearing of rash, lacy/reticulated appearance. Associations Arthralgia (older children); Transient aplastic crisis (Pre-existing hemolytic anemia + B19, presents pancytopenia); Infection in mother (during pregnancy). Management Supportive (good prognosis)."},
    {"id": "PEDS-U158", "ch": 19, "n": 6, "title": "Roseola Infantum / Exanthema Subitum (6th Disease)", "sec": "Roseola Infantum · p84", "qs": [], "guide": "Etiology Human herpes virus (HHV) 6, 7, echovirus 16; Age 6 months - 3 years. Clinical 1. Prodromal stage (1-4 days) Fever, Cough, Running nose. 2. Exanthematous phase (Day 4) Maculopapular rash, starts in trunk, ↓ fever after rash appears, No residual pigmentation. 3. Enanthem Nagayama spots: erythematous macules in soft palate and uvula. Treatment Supportive; Prognosis Good."},
    {"id": "PEDS-U159", "ch": 19, "n": 7, "title": "Hand Foot Mouth Disease (HFMD)", "sec": "HFMD · p84", "qs": [], "guide": "HFMD Age Preschool (<5 years). Causative Coxsackie A16, Enterovirus 71. Spread Direct contact/infected fomites (Eg used towel). Clinical Fever; Vesicles resolve over 4-5 days; Papulovesicular lesions in soles and palms; Blisters around oral cavity (First manifestation). Treatment Supportive. m/c complication Temporary loss of nails 4 weeks after initial infection."},
    {"id": "PEDS-U160", "ch": 19, "n": 8, "title": "Varicella / Chickenpox — Features, Complications, Treatment, Prevention", "sec": "Varicella · p84", "qs": [], "guide": "Varicella Causative varicella-zoster virus (ds DNA virus); Incubation 10-21 days; Droplet spread; Infectivity 24-48 hrs before rash → crusting of all lesions; Secondary attack rate 80%. Clinical Fever; Rash Day 2 of fever, lasts 3-5 days, Macule → Papule → Vesicle (pruritic), trunk → other areas, leaves hypo/hyperpigmented macules, Pleomorphic, Dew drop on a rose petal, Fluid filled vesicles. Complications Secondary bacterial (Staph aureus, Strep pyogenes), Neurological (Cerebellar ataxia, meningo-encephalitis), Reye's syndrome (Aspirin usage, hepatic encephalopathy). Diagnosis Clinical; Tzanck smear multinucleated giant cells (poor sensitivity); Serology Anti-IgM. Treatment Antipyretics Paracetamol; Acyclovir 20 mg/kg/dose x 4/day start within 48 hrs; Avoid Ibuprofen (↑ risk necrotizing fasciitis). Prevention Varicella vaccine (Live attenuated Oka strain, 2 doses SC: 15-18 months, 4-6 years); Post exposure (if not administered) Varicella vaccine + VZIG (immunocompromised, pregnant, neonate born to affected mother 5 days before to 2 days after delivery)."},
]

def q(num, sec, page, qtext, opts, ans, exp):
    assert len(opts)==4 and 0 <= ans <4
    return {"id": f"PEDS-C19-{num:03d}", "sec": sec, "page": page, "q": qtext, "opts": opts, "ans": ans, "exp": exp}

