RANGES = {153:(1,7),154:(8,35),155:(36,46),156:(47,59),157:(60,70),158:(71,78),159:(79,83),160:(84,108)}
UNIT_RANGES = {1:(1,7),2:(8,35),3:(36,46),4:(47,59),5:(60,70),6:(71,78),7:(79,83),8:(84,108)}
for u in UNITS:
    s,e = UNIT_RANGES[u["n"]]
    u["qs"] = [f"PEDS-C19-{i:03d}" for i in range(s,e+1)]

pages = [q["page"] for q in QUESTIONS]
assert pages == sorted(pages), f"Pages not sorted {pages[:10]}"
assert len(QUESTIONS)==108
assert len(UNITS)==8
for u in UNITS:
    s,e = UNIT_RANGES[u["n"]]
    assert len(u["qs"])==e-s+1
